def _load_ext():
    """JIT-build the fused kernels (once per process)."""
    global _EXT
    if _EXT is not None:
        return _EXT
    with _EXT_LOCK:
        if _EXT is None:
            from torch.utils.cpp_extension import load_inline

            os.environ.setdefault("TORCH_CUDA_ARCH_LIST", "10.0a")
            _EXT = load_inline(
                name="fk_af3_msa_module_fused",
                cpp_sources=_CPP_DECL,
                cuda_sources=_CUDA_SRC,
                functions=["msa_stack"],
                extra_cuda_cflags=["-O3", "-lineinfo", "--expt-relaxed-constexpr"],
                verbose=False,
            )
    return _EXT


