class MSAModuleBlock(nn.Module):
    """Single block of AF3 Algorithm 8.

    Args:
        c_m: MSA channel dimension
        c_z: Pair channel dimension
        c_hidden_msa_att: Hidden dim in MSA attention
        c_hidden_opm: Hidden dim in outer product mean
        c_hidden_mul: Hidden dim in triangle multiplication
        c_hidden_pair_att: Hidden dim in triangle attention
        no_heads_msa: Heads for MSA attention
        no_heads_pair: Heads for triangle attention
        transition_n: Transition layer scale
        msa_dropout: MSA dropout rate
        pair_dropout: Pair dropout rate
        opm_first: Whether OPM comes before MSA attention
    """

    def __init__(
        self,
        c_m: int,
        c_z: int,
        c_hidden_msa_att: int,
        c_hidden_opm: int,
        c_hidden_mul: int,
        c_hidden_pair_att: int,
        no_heads_msa: int,
        no_heads_pair: int,
        transition_n: int,
        msa_dropout: float = 0.0,
        pair_dropout: float = 0.0,
        opm_first: bool = True,
        fuse_projection_weights: bool = False,
        inf: float = 1e9,
        eps: float = 1e-3,
        last_block: bool = False,
    ):
        super().__init__()
        self.opm_first = opm_first
        self.skip_msa_update = last_block and opm_first

        if not self.skip_msa_update:
            self.msa_att_row = MSARowAttentionWithPairBias(
                c_m=c_m, c_z=c_z,
                c_hidden=c_hidden_msa_att,
                no_heads=no_heads_msa,
                inf=inf,
            )

            self.msa_transition = SwiGLUTransition(c_in=c_m, n=transition_n)

        self.outer_product_mean = OuterProductMean(
            c_m=c_m, c_z=c_z, c_hidden=c_hidden_opm, eps=eps,
        )

        self.pair_stack = PairBlock(
            c_z=c_z,
            c_hidden_mul=c_hidden_mul,
            c_hidden_pair_att=c_hidden_pair_att,
            no_heads_pair=no_heads_pair,
            transition_n=transition_n,
            pair_dropout=pair_dropout,
            inf=inf,
        )

    def forward(
        self,
        m: torch.Tensor,
        z: torch.Tensor,
        msa_mask: torch.Tensor,
        pair_mask: torch.Tensor,
        chunk_size: int | None = None,
        use_deepspeed_evo_attention: bool = False,
        use_cueq_triangle_kernels: bool = False,
        use_lma: bool = False,
        inplace_safe: bool = False,
        _mask_trans: bool = True,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Args:
            m:        [*, N_seq, N_res, C_m] MSA embedding
            z:        [*, N_res, N_res, C_z] pair embedding
            msa_mask: [*, N_seq, N_res] MSA mask
            pair_mask:[*, N_res, N_res] pair mask

        Returns:
            (m, z): updated MSA and pair embeddings
        """
        if self.opm_first:
            z = z + self.outer_product_mean(m, mask=msa_mask)

        if not self.skip_msa_update:
            m = m + self.msa_att_row(m, z=z, mask=pair_mask)
            m = m + self.msa_transition(m)

        if not self.opm_first:
            z = z + self.outer_product_mean(m, mask=msa_mask)

        z = self.pair_stack(z=z, pair_mask=pair_mask)

        return m, z


def _t(w):
    """nn.Linear weight [out, in] -> contiguous [in, out] for the kernels."""
    return w.detach().t().contiguous().to(torch.bfloat16).reshape(-1)


def _pk(wt):
    """[K, NN] -> [K/8][NN/2][8] of bf16x2 (the kernels' "pk" weight layout).

    Groups the 8 k-steps of one output-column *pair* into 32 contiguous bytes so
    a thread streams its two columns with 16-byte loads; see gemm_pk.
    """
    K, NN = wt.shape
    assert K % 8 == 0 and NN % 2 == 0, (K, NN)
    return (wt.reshape(K // 8, 8, NN // 2, 2).permute(0, 2, 1, 3)
              .contiguous().reshape(-1))


def _tp(w):
    """nn.Linear weight -> pk layout."""
    return _pk(w.detach().t().contiguous().to(torch.bfloat16))


def _tilvp(ws):
    """Interleave projections along the output dim, then pk-pack.

    The fused epilogues combine several projections of the *same* channel
    (SwiGLU's a/b, triangle-mul's a_p/a_g/b_p/b_g, attention's q/k/v/g).  Packing
    those adjacently makes the two columns a thread loads the pair it has to
    combine, so nothing has to go through shared memory.
    """
    st = torch.stack([w.detach() for w in ws], dim=1)
    w = st.reshape(st.shape[0] * st.shape[1], st.shape[2])
    return _pk(w.t().contiguous().to(torch.bfloat16))


class MSAModuleStack(nn.Module):
    """AF3 Algorithm 8: MSA module stack.

    Args:
        c_m: MSA channel dimension
        c_z: Pair channel dimension
        c_hidden_msa_att: Hidden dim in MSA attention
        c_hidden_opm: Hidden dim in outer product mean
        c_hidden_mul: Hidden dim in triangle multiplication
        c_hidden_pair_att: Hidden dim in triangle attention
        no_heads_msa: Heads for MSA attention
        no_heads_pair: Heads for triangle attention
        no_blocks: Number of MSA module blocks
        transition_n: Transition scale
        opm_first: Whether OPM comes before MSA attention
    """

    def __init__(
        self,
        c_m: int,
        c_z: int,
        c_hidden_msa_att: int,
        c_hidden_opm: int,
        c_hidden_mul: int,
        c_hidden_pair_att: int,
        no_heads_msa: int,
        no_heads_pair: int,
        no_blocks: int,
        transition_n: int,
        msa_dropout: float = 0.0,
        pair_dropout: float = 0.0,
        opm_first: bool = True,
        fuse_projection_weights: bool = False,
        blocks_per_ckpt: int | None = None,
        inf: float = 1e9,
        eps: float = 1e-3,
        **kwargs,
    ):
        super().__init__()
        self.blocks = nn.ModuleList([
            MSAModuleBlock(
                c_m=c_m, c_z=c_z,
                c_hidden_msa_att=c_hidden_msa_att,
                c_hidden_opm=c_hidden_opm,
                c_hidden_mul=c_hidden_mul,
                c_hidden_pair_att=c_hidden_pair_att,
                no_heads_msa=no_heads_msa,
                no_heads_pair=no_heads_pair,
                transition_n=transition_n,
                msa_dropout=msa_dropout,
                pair_dropout=pair_dropout,
                opm_first=opm_first,
                inf=inf,
                eps=eps,
                last_block=(i == no_blocks - 1),
            )
            for i in range(no_blocks)
        ])
        # The fused path is specialized to the shapes/hyper-parameters this op
        # was captured with; anything else falls back to the module tree above.
        self._fast_ok = (
            c_m == 64 and c_z == 128 and c_hidden_msa_att == 8
            and c_hidden_opm == 32 and c_hidden_mul == 128
            and c_hidden_pair_att == 32 and no_heads_msa == 8
            and no_heads_pair == 4 and transition_n == 4 and opm_first
            and float(inf) == 1e9 and float(eps) == 1e-3 and no_blocks >= 1
        )
        self._packed = False
        self._wb = None
        self._wf = None
        self._scratch = None

    # -- fused-path setup -------------------------------------------------
    def _pack(self, dev):
        nb = len(self.blocks)
        wb = torch.zeros(nb * _WB_STRIDE, dtype=torch.bfloat16, device=dev)
        wf = torch.zeros(nb * _WF_STRIDE, dtype=torch.float32, device=dev)

        def put_b(bi, key, val):
            o, n = _WB_OFF[key]
            assert val.numel() == n, (key, val.numel(), n)
            wb[bi * _WB_STRIDE + o: bi * _WB_STRIDE + o + n] = val

        def put_f(bi, key, val):
            o, n = _WF_OFF[key]
            assert val.numel() == n, (key, val.numel(), n)
            wf[bi * _WF_STRIDE + o: bi * _WF_STRIDE + o + n] = val.detach().float().reshape(-1)

        for bi, blk in enumerate(self.blocks):
            o = blk.outer_product_mean
            put_b(bi, "OPM_W1T", _t(o.linear_1.weight))
            put_b(bi, "OPM_W2T", _t(o.linear_2.weight))
            put_b(bi, "OPM_WOUT", _tp(o.linear_out.weight))
            put_f(bi, "OPM_LNW", o.layer_norm.weight)
            put_f(bi, "OPM_LNB", o.layer_norm.bias)
            put_f(bi, "OPM_OB", o.linear_out.bias)
            if not blk.skip_msa_update:
                a = blk.msa_att_row
                put_b(bi, "MSA_WZ", _t(a.linear_z.weight))
                put_b(bi, "MSA_WV", _t(a.linear_v.weight))
                put_b(bi, "MSA_WG", _t(a.linear_g.weight))
                put_b(bi, "MSA_WO", _t(a.linear_o.weight))
                put_f(bi, "MSA_LNMW", a.layer_norm_m.weight)
                put_f(bi, "MSA_LNMB", a.layer_norm_m.bias)
                put_f(bi, "MSA_LNZW", a.layer_norm_z.weight)
                put_f(bi, "MSA_LNZB", a.layer_norm_z.bias)
                t = blk.msa_transition
                put_b(bi, "MTR_WAB", _tilvp([t.swiglu.linear_a.weight, t.swiglu.linear_b.weight]))
                put_b(bi, "MTR_WO", _t(t.linear_out.weight))
                put_f(bi, "MTR_LNW", t.layer_norm.weight)
                put_f(bi, "MTR_LNB", t.layer_norm.bias)
            ps = blk.pair_stack
            for pre, tm in (("TMO", ps.tri_mul_out), ("TMI", ps.tri_mul_in)):
                put_b(bi, pre + "_W4", _tilvp([
                    tm.linear_a_p.weight, tm.linear_a_g.weight,
                    tm.linear_b_p.weight, tm.linear_b_g.weight]))
                put_b(bi, pre + "_WG", _tp(tm.linear_g.weight))
                put_b(bi, pre + "_WZ", _tp(tm.linear_z.weight))
                put_f(bi, pre + "_LIW", tm.layer_norm_in.weight)
                put_f(bi, pre + "_LIB", tm.layer_norm_in.bias)
                put_f(bi, pre + "_LOW", tm.layer_norm_out.weight)
                put_f(bi, pre + "_LOB", tm.layer_norm_out.bias)
            for pre, ta in (("TAS", ps.tri_att_start), ("TAE", ps.tri_att_end)):
                put_b(bi, pre + "_WZ", _t(ta.linear_z.weight))
                put_b(bi, pre + "_W4", _tilvp([
                    ta.mha.linear_q.weight, ta.mha.linear_k.weight,
                    ta.mha.linear_v.weight, ta.mha.linear_g.weight]))
                put_b(bi, pre + "_WO", _tp(ta.mha.linear_o.weight))
                put_f(bi, pre + "_LNW", ta.layer_norm.weight)
                put_f(bi, pre + "_LNB", ta.layer_norm.bias)
            pt = ps.pair_transition
            put_b(bi, "PTR_WAB", _tilvp([pt.swiglu.linear_a.weight, pt.swiglu.linear_b.weight]))
            put_b(bi, "PTR_WO", _tp(pt.linear_out.weight))
            put_f(bi, "PTR_LNW", pt.layer_norm.weight)
            put_f(bi, "PTR_LNB", pt.layer_norm.bias)

        self._wb, self._wf = wb, wf
        self._scratch = torch.empty(_SCRATCH_ELEMS, dtype=torch.bfloat16, device=dev)
        self._nb = nb
        self._packed = True

    def _ref_forward(self, m, z, msa_mask, pair_mask):
        for block in self.blocks:
            m, z = block(m=m, z=z, msa_mask=msa_mask, pair_mask=pair_mask)
        return m, z

    def forward(
        self,
        m: torch.Tensor,
        z: torch.Tensor,
        msa_mask: torch.Tensor,
        pair_mask: torch.Tensor,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Args:
            m:        [*, N_seq, N_res, C_m] MSA embedding
            z:        [*, N_res, N_res, C_z] pair embedding
            msa_mask: [*, N_seq, N_res] MSA mask
            pair_mask:[*, N_res, N_res] pair mask

        Returns:
            (m, z): updated MSA and pair embeddings
        """
        if (self._fast_ok and m.is_cuda and m.dtype is torch.bfloat16
                and z.dtype is torch.bfloat16
                and tuple(m.shape) == (1, 8, 16, 64)
                and tuple(z.shape) == (1, 16, 16, 128)
                and msa_mask.dtype is torch.bfloat16
                and pair_mask.dtype is torch.bfloat16):
            ext = _load_ext()
            if not self._packed:
                self._pack(m.device)
            if not m.is_contiguous():
                m = m.contiguous()
            if not z.is_contiguous():
                z = z.contiguous()
            if not msa_mask.is_contiguous():
                msa_mask = msa_mask.contiguous()
            if not pair_mask.is_contiguous():
                pair_mask = pair_mask.contiguous()
            zout = torch.empty_like(z)
            mout = torch.empty_like(m)
            ext.msa_stack(z, m, zout, mout, self._wb, self._wf, self._scratch,
                          msa_mask, pair_mask, self._nb)
            return mout, zout
        return self._ref_forward(m, z, msa_mask, pair_mask)


